function Config.SkillData.data_get_effect_data_fun(slot0)
	slot1 = Config.SkillData.data_get_effect_data[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.SkillData.data_get_effect_data[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

